cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, SI
	JMP  cntdone

cnttail:
	CMPQ    SI, R8
	JAE     cntdone
	MOVBLZX (R10)(SI*1), CX
	CMPB    CX, (DI)(SI*1)
	JNE     cntdone
	INCQ    SI
	JMP     cnttail

cntdone:
	CMPQ SI, AX
	JLE  reload
	MOVQ SI, AX             // a longer match
	MOVL DX, 4(SP)
	CMPQ SI, R8
	JEQ  done               // best possible, avoids read overflow on next attempt

reload:
	MOVL -3(DI)(AX*1), CX

next:
	CMPL DX, 0(SP)
	JLS  done               // matchIndex <= minChain
	ANDL R13, DX
	MOVL (R11)(DX*4), DX    // C: NEXT_IN_CHAIN(matchIndex, chainMask)
	DECL R14
	JNE  walk

done:
	MOVQ P_B, SI
	CMPQ AX, $3
	JLE  none
	SUBL 4(SP), BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)
	RET

none:
	MOVL $999999999, BX     // offBaseNotFound
	RET

bad:
	MOVQ P_B, SI
	MOVQ $-1, AX
	RET

// func lazyHc5(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, hash chain) for mls 5: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyHc5(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·hcSearch5(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·hcSearch5(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·hcSearch5(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping
	MOVL $0, P_SKIP

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// hcSearch6: hcFindBestMatch (noDict, mls 6) at DI = ip, R15 = p,
// with insertAndFindFirstIndexInternal. Returns AX = ml (below 4: none; -1: a
// chain entry at or after ip, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
TEXT ·hcSearch6(SB), NOSPLIT, $16-0
	MOVQ P_B, R9
	MOVL P_BASEIDX, BX
	SUBQ BX, R9             // b - baseIdx: an index addresses b directly
	ADDL DI, BX             // curr
	MOVQ P_HASHTABLE, R10
	MOVQ P_CHAIN, R11
	MOVL P_CHAINMASK, R13
	MOVQ $0xcf1bbcdcbf9b0000, R14
	MOVQ P_HSHIFT, CX

	// insert [nextToUpdate, curr), or only nextToUpdate when lazy skipping
	// (C: ZSTD_insertAndFindFirstIndex_internal). nextToUpdate >= baseIdx
	// (lazyHcRun), and the 8 bytes hashed at each index lie before
	// ip + 8 <= iend.
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL BX, SI             // the insert limit
	CMPL P_SKIP, $0
	JEQ  insck
	LEAL 1(R8), SI
	CMPL SI, BX
	JBE  insck
	MOVL BX, SI
	JMP  insck

ins:
	MOVQ  (R9)(R8*1), AX
	IMULQ R14, AX
	SHRQ  CX, AX
	MOVL  (R10)(AX*4), DX
	MOVL  R8, R12
	ANDL  R13, R12
	MOVL  DX, (R11)(R12*4)  // C: NEXT_IN_CHAIN(idx, chainMask) = hashTable[h]
	MOVL  R8, (R10)(AX*4)
	INCL  R8

insck:
	CMPL R8, SI
	JB   ins
	MOVQ P_NEXT, AX
	MOVL BX, (AX)           // nextToUpdate = curr
	MOVQ (R9)(BX*1), AX
	IMULQ R14, AX
	SHRQ CX, AX
	MOVL (R10)(AX*4), DX    // matchIndex

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, R12
	MOVL BX, AX
	SUBL R12, AX
	CMPL AX, P_MAXDIST
	JLS  lowok
	MOVL BX, R12
	SUBL P_MAXDIST, R12

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, R12

lowset:
	// minChain = curr > chainSize ? curr - chainSize : 0
	XORL AX, AX
	MOVL BX, CX
	LEAL 1(R13), R10
	SUBL R10, CX
	CMOVLHI CX, AX
	MOVL AX, 0(SP)
	MOVL $0, 4(SP)          // best matchIndex
	MOVL P_ATTEMPTS, R14
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip
	MOVQ P_B, SI
	ADDQ SI, DI             // ip
	MOVL $3, AX             // ml
	MOVL (DI), CX           // read32(ip + ml - 3)

walk:
	CMPL DX, R12
	JB   done               // below lowLimit
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (lazyHcRun
	// checks lowestValid >= baseIdx and lowestValid <= ip's index, so
	// curr - lowestValid does not wrap). So R9 + DX lies in b[0:ip], and
	// the compare and count read only up to the iLimit - ip bytes b[ip:]
	// holds: match + ml + 1 <= ip + ml + 1, and ml < iLimit - ip here.
	CMPL DX, BX
	JAE  bad
	LEAQ (R9)(DX*1), R10
	CMPL CX, -3(R10)(AX*1)
	JNE  next
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL SI, SI
	CMPQ R8, $8
	JB   cnttail
	MOVQ (R10), CX
	XORQ (DI), CX
	JNE  cntdiff
	MOVL $8, SI
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(SI), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (R10)(SI*1), Y0
	VPCMPEQB  (DI)(SI*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, SI
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, SI
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(SI), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (R10)(SI*1), CX
	XORQ (DI)(SI*1), CX
	JNE  cntdiff
	ADDQ $8, SI
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, SI
	JMP  cntdone

cnttail:
	CMPQ    SI, R8
	JAE     cntdone
	MOVBLZX (R10)(SI*1), CX
	CMPB    CX, (DI)(SI*1)
	JNE     cntdone
	INCQ    SI
	JMP     cnttail

cntdone:
	CMPQ SI, AX
	JLE  reload
	MOVQ SI, AX             // a longer match
	MOVL DX, 4(SP)
	CMPQ SI, R8
	JEQ  done               // best possible, avoids read overflow on next attempt

reload:
	MOVL -3(DI)(AX*1), CX

next:
	CMPL DX, 0(SP)
	JLS  done               // matchIndex <= minChain
	ANDL R13, DX
	MOVL (R11)(DX*4), DX    // C: NEXT_IN_CHAIN(matchIndex, chainMask)
	DECL R14
	JNE  walk

done:
	MOVQ P_B, SI
	CMPQ AX, $3
	JLE  none
	SUBL 4(SP), BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)
	RET

none:
	MOVL $999999999, BX     // offBaseNotFound
	RET

bad:
	MOVQ P_B, SI
	MOVQ $-1, AX
	RET

// func lazyHc6(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, hash chain) for mls 6: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyHc6(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·hcSearch6(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·hcSearch6(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·hcSearch6(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping
	MOVL $0, P_SKIP

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET
